using System.ComponentModel;
using System.Net.Http;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class ApiTools
{
    /// <summary>
    /// Calls an external HTTP API and returns the response body as text.
    /// </summary>
    [McpServerTool(Name = "fetch_url"), Description("Fetches the content of a URL via HTTP GET and returns the response body.")]
    public static async Task<string> FetchUrl(
        IHttpClientFactory httpClientFactory,
        [Description("The URL to fetch")] string url,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("Default");
